syntax:
For a class with virtual functions:

// Class declaration
class ClassName {
public:
    virtual void functionName();
    // ... other members
};

// Compiler-generated internal structures
// Each class with virtual functions has a vtable:
// vtable for ClassName: array of function pointers
// Each object of ClassName contains a hidden pointer to its vtable

// During object creation, the constructor sets the vtable pointer
// Virtual function calls are dispatched via the vtable pointer

// Example of a virtual function call:
// objectPtr->functionName(); // internally: *(objectPtr->vptr)[index]()

code_example:
class Base {
public:
    virtual void foo() { /* base implementation */ }
};
class Derived : public Base {
public:
    void foo() override { /* derived implementation */ }
};

int main() {
    Base* p = new Derived();
    p->foo(); // invokes Derived::foo via vtable dispatch
    delete p;
}
